```python
def is_prime(n):
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def f(inputs):
    result = []
    for n in inputs:
        if n == 0:
            break
        count = sum(1 for i in range(2, n+1) if is_prime(i))
        result.append(count)
    return result
```
